#include "hal.h"

#define LOOP_MS   100
#define TEMP_HIGH 420
#define TEMP_LOW  180

const char *err_name(err_t e);

/* Called every LOOP_MS. */
void control_step(void)
{
    int16_t t;
    err_t e = i2c_read_temp(&t);

    if (e != E_OK) {
        log_warn(err_name(e));
        return;
    }
    heater_set(t < TEMP_LOW);
    valve_set(t > TEMP_HIGH);
    pump_set_pct(t > TEMP_HIGH ? 100 : 35);
}

