use std::path::{Path, PathBuf};
use std::time::SystemTime;

const MAX_DEPTH: usize = 8;

pub struct Entry {
    pub path: PathBuf,
    pub len: u64,
    pub modified: SystemTime,
}

/// Regular files below `root`. Symbolic links are never followed or listed.
pub fn scan(root: &Path) -> std::io::Result<Vec<Entry>> {
    let mut out = Vec::new();
    walk(root, 0, &mut out)?;
    Ok(out)
}

fn walk(dir: &Path, depth: usize, out: &mut Vec<Entry>) -> std::io::Result<()> {
    if depth > MAX_DEPTH {
        return Ok(());
    }
    for item in std::fs::read_dir(dir)? {
        let item = item?;
        let meta = item.metadata()?;
        if meta.is_dir() {
            walk(&item.path(), depth + 1, out)?;
        } else if meta.is_file() {
            out.push(Entry { path: item.path(), len: meta.len(), modified: meta.modified()? });
        }
    }
    Ok(())
}

