#pragma once
#include <stdbool.h>
#include <stdint.h>

#define RX_BUF_SIZE 384u

typedef struct {
    volatile uint8_t buf[RX_BUF_SIZE];
    volatile uint8_t head; /* written by the ISR only */
    volatile uint8_t tail; /* written by the main loop only */
} ring_t;

bool ring_put(ring_t *r, uint8_t byte);
bool ring_get(ring_t *r, uint8_t *byte);
uint16_t ring_count(const ring_t *r);

files.src/ring.c:
#include "ring.h"

#define RX_MASK (RX_BUF_SIZE - 1u)

bool ring_put(ring_t *r, uint8_t byte)
{
    uint8_t next = (r->head + 1u) & RX_MASK;

    if (next == r->tail)
        return false;
    r->buf[r->head] = byte;
    r->head = next;
    return true;
}

bool ring_get(ring_t *r, uint8_t *byte)
{
    if (r->tail == r->head)
        return false;
    *byte = r->buf[r->tail];
    r->tail = (r->tail + 1u) & RX_MASK;
    return true;
}

uint16_t ring_count(const ring_t *r)
{
    return (r->head - r->tail) & RX_MASK;
}

files.src/uart.c:
#include "ring.h"

extern uint8_t uart_read_dr(void);

ring_t rx;
volatile uint32_t rx_drops;

/* Cortex-M0, single core. The only producer. */
void UART_IRQHandler(void)
{
    if (!ring_put(&rx, uart_read_dr()))
        rx_drops++;
}

/* Called from the main loop, the only consumer. */
bool uart_frame(uint8_t *out, uint16_t len)
{
    if (ring_count(&rx) < len)
        return false;
    for (uint16_t i = 0; i < len; i++)
        ring_get(&rx, &out[i]);
    return true;
}

files.tests/test_ring.c:
#include <assert.h>
#include "ring.h"

int main(void)
{
    static ring_t r;
    uint8_t b;

    for (int round = 0; round < 5; round++) {
        for (int i = 0; i < 370; i++)
            assert(ring_put(&r, (uint8_t)i));
        assert(ring_count(&r) == 370);
        for (int i = 0; i < 370; i++)
            assert(ring_get(&r, &b) && b == (uint8_t)i);
    }
    return 0;
}

