import re
def code(path):
    return re.sub(r'//[^\n]*|/\*[\s\S]*?\*/', '', open(path).read())
h, c = code('include/ring.h'), code('src/ring.c')
both = h + c
alias = dict((b, a.strip()) for a, b in re.findall(r'typedef\s+([\w ]+?)\s+(\w+)\s*;', both))
def narrow(t):
    t = t.replace('volatile', '').replace('_Atomic', '').strip()
    t = alias.get(t, t)
    return t in ('uint8_t', 'unsigned char', 'char', 'int8_t', 'uint_least8_t')
for name in ('head', 'tail'):
    decl = re.search(r'^\s*([\w ]+?)\s+' + name + r'\s*;', h, re.M)
    if decl:
        assert not narrow(decl.group(1)), decl.group(0)
    else:
        decl = re.search(r'^\s*([\w ]+?)\s+(head\s*,\s*tail|tail\s*,\s*head)\s*;', h, re.M)
        assert decl and not narrow(decl.group(1))
for t, rhs in re.findall(r'\b(\w+)\s+\w+\s*=\s*([^;]+);', c):
    if 'buf' not in rhs and re.search(r'\b(head|tail|next)\b', rhs):
        assert not narrow(t), (t, rhs)

