class MemoryStore:
    """Development stand-in for the shared key-value store."""

    def __init__(self):
        self._data = {}

    def get(self, key):
        value = self._data.get(key)
        return dict(value) if value is not None else None

    def put(self, key, value):
        self._data[key] = dict(value)

    def delete(self, key):
        self._data.pop(key, None)

