from svc.config import IDLE_SECONDS


def create(store, sid, user, now):
    store.put(sid, {"user": user, "created_at": now, "last_seen": now})


def current_user(store, sid, now):
    session = store.get(sid)
    if session is None:
        return None
    if now - session["created_at"] > IDLE_SECONDS:
        store.delete(sid)
        return None
    session["last_seen"] = now
    return session["user"]

