import sys
sys.path.insert(0, '.')
from svc import sessions
class Copies:
    def __init__(self):
        self.d = {}
    def get(self, k):
        return dict(self.d[k]) if k in self.d else None
    def put(self, k, v, *a, **kw):
        self.d[k] = dict(v)
    def delete(self, k):
        self.d.pop(k, None)
s = Copies()
sessions.create(s, 's', 'ada', 0)
def slides():
    """Both causes are gone, whatever the design: a busy session lives, an idle one ends."""
    t = Copies()
    sessions.create(t, 'x', 'ada', 0)
    if any(sessions.current_user(t, 'x', hour * 3600) != 'ada' for hour in range(1, 25)):
        return False
    return sessions.current_user(t, 'x', 24 * 3600 + 28801) is None
def isolated():
    for k, v in list(s.d['s'].items()):
        if k != 'created_at' and isinstance(v, (int, float)):
            s.d['s'][k] = v + 30000
    saved = dict(s.d['s'])
    stays = sessions.current_user(s, 's', 40000) == 'ada'
    s.d['s'] = dict(saved)
    return stays and sessions.current_user(s, 's', 30000 + 28801) is None
assert slides() or isolated()

