def isolated():
    before = dict(s.d['s'])
    stays = sessions.current_user(s, 's', 1000) == 'ada'
    after = s.d.get('s', {})
    return stays and any(isinstance(v, (int, float)) and after.get(k) == v + 1000 for k, v in before.items())
assert slides() or isolated()

