pub mod preview;
pub mod tag;

use preview::{preview, PREVIEW_MAX};

/// One input line is `service<TAB>message`.
pub fn parse(line: &str) -> Option<(&str, &str)> {
    let (service, msg) = line.split_once('\t')?;
    (!service.is_empty()).then_some((service, msg))
}

pub struct Record {
    pub tag: String,
    pub preview: [u8; PREVIEW_MAX + 3],
}

pub fn ingest(input: &str) -> Vec<Record> {
    input
        .lines()
        .filter_map(parse)
        .map(|(service, msg)| {
            let text = preview(msg);
            let mut field = [0u8; PREVIEW_MAX + 3];
            field[..text.len()].copy_from_slice(text.as_bytes());
            Record { tag: tag::tag(service), preview: field }
        })
        .collect()
}

