/*
 * tapbuf: one shared 4 KiB buffer.
 * read() returns a snapshot from offset 0 and ignores the file position.
 * write() takes a struct tap_hdr followed by hdr.len bytes.
 * The ioctls are allowed on every open descriptor, also a read-only one.
 */
#include <linux/fs.h>
#include <linux/miscdevice.h>
#include <linux/module.h>
#include <linux/slab.h>
#include <linux/spinlock.h>
#include <linux/string.h>
#include <linux/uaccess.h>

#define TAP_SIZE 4096

struct tap_hdr { __u32 off; __u32 len; };
struct tap_info { __u8 version; __u32 size; };

#define TAP_IOC_INFO  _IOR('t', 1, struct tap_info)
#define TAP_IOC_RESET _IO('t', 2)
#define TAP_IOC_SUM   _IOR('t', 3, __u32)

static struct {
	spinlock_t lock;
	u8 *buf;
} tap;

static int tap_open(struct inode *inode, struct file *file)
{
	return nonseekable_open(inode, file);
}

static ssize_t tap_read(struct file *file, char __user *ubuf, size_t n, loff_t *pos)
{
	unsigned long flags;
	ssize_t ret;

	n = min_t(size_t, n, TAP_SIZE);
	spin_lock_irqsave(&tap.lock, flags);
	ret = copy_to_user(ubuf, tap.buf, n) ? -EFAULT : n;
	spin_unlock_irqrestore(&tap.lock, flags);
	return ret;
}

static ssize_t tap_write(struct file *file, const char __user *ubuf, size_t n, loff_t *pos)
{
	struct tap_hdr h;
	unsigned long flags;
	u8 *data;

	if (n < sizeof(h))
		return -EINVAL;
	if (copy_from_user(&h, ubuf, sizeof(h)))
		return -EFAULT;
	if (n - sizeof(h) != h.len || h.off + h.len > TAP_SIZE)
		return -EINVAL;

	data = memdup_user(ubuf + sizeof(h), h.len);
	if (IS_ERR(data))
		return PTR_ERR(data);
	spin_lock_irqsave(&tap.lock, flags);
	memcpy(tap.buf + h.off, data, h.len);
	spin_unlock_irqrestore(&tap.lock, flags);
	kfree(data);
	return n;
}

static long tap_get_info(void __user *arg)
{
	struct tap_info info;

	info.version = 1;
	info.size = TAP_SIZE;
	return copy_to_user(arg, &info, sizeof(info)) ? -EFAULT : 0;
}

static void tap_reset(void)
{
	unsigned long flags;

	spin_lock_irqsave(&tap.lock, flags);
	memset(tap.buf, 0, TAP_SIZE);
	spin_unlock_irqrestore(&tap.lock, flags);
}

static long tap_sum(__u32 __user *arg)
{
	unsigned long flags;
	__u32 sum = 0;
	int i;

	spin_lock_irqsave(&tap.lock, flags);
	for (i = 0; i < TAP_SIZE; i++)
		sum += tap.buf[i];
	spin_unlock_irqrestore(&tap.lock, flags);
	return put_user(sum, arg);
}

static long tap_ioctl(struct file *file, unsigned int cmd, unsigned long arg)
{
	switch (cmd) {
	case TAP_IOC_INFO:
		return tap_get_info((void __user *)arg);
	case TAP_IOC_RESET:
		tap_reset();
		return 0;
	case TAP_IOC_SUM:
		return tap_sum((__u32 __user *)arg);
	}
	return -ENOTTY;
}

static const struct file_operations tap_fops = {
	.owner          = THIS_MODULE,
	.open           = tap_open,
	.read           = tap_read,
	.write          = tap_write,
	.unlocked_ioctl = tap_ioctl,
	.compat_ioctl   = compat_ptr_ioctl,
};

static struct miscdevice tap_misc = {
	.minor = MISC_DYNAMIC_MINOR,
	.name  = "tapbuf",
	.fops  = &tap_fops,
	.mode  = 0600,
};

static int __init tap_init(void)
{
	spin_lock_init(&tap.lock);
	tap.buf = kzalloc(TAP_SIZE, GFP_KERNEL);
	if (!tap.buf)
		return -ENOMEM;
	return misc_register(&tap_misc);
}

static void __exit tap_exit(void)
{
	misc_deregister(&tap_misc);
	kfree(tap.buf);
}

module_init(tap_init);
module_exit(tap_exit);
MODULE_LICENSE("GPL");

