#pragma once
#include <cstdint>
#include <functional>
#include <vector>

enum class Kind { Frame, Unknown };

struct Event {
    Kind kind;
    uint8_t type, seq, lost;
    std::vector<uint8_t> payload;
};

class Decoder {
  public:
    explicit Decoder(std::function<void(const Event&)> emit) : emit_(std::move(emit)) {}
    void feed(const uint8_t* data, size_t n);

  private:
    void drop(size_t n) { buf_.erase(buf_.begin(), buf_.begin() + n); }
    std::function<void(const Event&)> emit_;
    std::vector<uint8_t> buf_;
    bool have_seq_ = false;
    uint8_t last_seq_ = 0;
};

