#include "decoder.hpp"

#include <algorithm>

namespace {
constexpr uint8_t kMagic = 0xA7;
constexpr size_t kHeader = 6;
constexpr size_t kMaxPayload = 1024;

bool known(uint8_t type) { return type == 0x01 || type == 0x02 || type == 0x81; }

uint8_t crc8(const uint8_t* p, size_t n) {
    uint8_t crc = 0;
    while (n--) {
        crc ^= *p++;
        for (int i = 0; i < 8; ++i)
            crc = static_cast<uint8_t>((crc & 0x80) ? (crc << 1) ^ 0x07 : crc << 1);
    }
    return crc;
}
}  // namespace

void Decoder::feed(const uint8_t* data, size_t n) {
    buf_.insert(buf_.end(), data, data + n);
    for (;;) {
        buf_.erase(buf_.begin(), std::find(buf_.begin(), buf_.end(), kMagic));
        if (buf_.size() < kHeader)
            return;
        if ((buf_[1] >> 4) != 2) {
            drop(1);
            continue;
        }
        const size_t len = (size_t{buf_[4]} << 8) | buf_[5];
        if (len >= kMaxPayload) {
            drop(1);
            continue;
        }
        const size_t total = kHeader + len + 1;
        if (buf_.size() < total)
            return;
        if (crc8(buf_.data(), total - 1) != buf_[total - 1]) {
            drop(total);
            continue;
        }
        const uint8_t type = buf_[2], seq = buf_[3];
        const uint8_t lost = have_seq_ ? static_cast<uint8_t>(seq - last_seq_ - 1) : 0;
        have_seq_ = true;
        last_seq_ = seq;

        if (known(type) || !(type & 0x40)) {
            const Kind kind = known(type) ? Kind::Frame : Kind::Unknown;
            emit_({kind, type, seq, lost, {buf_.begin() + kHeader, buf_.begin() + kHeader + len}});
        }
        drop(total);
    }
}

