import json
from pathlib import Path

DEFAULTS = {"timeout": 30, "workers": 4, "verbose": False, "hooks": ["format"]}


def _chain(path, seen):
    if path in seen:
        return []
    seen.add(path)
    data = json.loads(path.read_text())
    out = []
    for parent in data.get("extends", []):
        out += _chain(path.parent / f"{parent}.json", seen)
    return out + [(path, data)]


def _merge(conf, data):
    for key, value in data.items():
        if key not in DEFAULTS:
            continue
        if key != "hooks":
            conf[key] = value
            continue
        for hook in value:
            if hook.startswith("-"):
                conf[key] = [h for h in conf[key] if h != hook[1:]]
            elif hook not in conf[key]:
                conf[key] = conf[key] + [hook]


def resolve(profile, env, cli, cpus, root=Path("profiles")):
    chain = _chain(root / f"{profile}.json", set())
    local = root / f"{profile}.local.json"
    if local.exists():
        chain.append((local, json.loads(local.read_text())))

    conf = dict(DEFAULTS)
    for _, data in chain:
        _merge(conf, data)

    for key in ("timeout", "workers", "verbose"):
        raw = env.get(f"BUILD_{key.upper()}")
        if raw is not None:
            conf[key] = raw in ("1", "true") if key == "verbose" else int(raw)
    for key in ("timeout", "workers"):
        if cli.get(key):
            conf[key] = cli[key]

    if "sanitize" in conf["hooks"]:
        conf["timeout"] *= 3
    conf["workers"] = min(conf["workers"], cpus - 1)
    return conf, [str(path) for path, _ in chain]

