// Express 5. Mounted at /orgs/:org behind requireMember.

export async function listProjects(req, res) {
  const sort = req.query.sort || 'name';
  const { rows } = await req.db.query(
    `SELECT id, name, archived FROM projects WHERE org_id = $1 ORDER BY ${sort}`,
    [req.member.org_id],
  );
  res.json(rows);
}

export async function getProject(req, res) {
  const { rows } = await req.db.query(
    'SELECT id, name, archived FROM projects WHERE id = $1 AND org_id = $2',
    [req.params.id, req.member.org_id],
  );
  if (!rows.length) return res.sendStatus(404);
  res.json(rows[0]);
}

export async function updateProject(req, res) {
  const row = await req.db.updateRow(
    'projects',
    { id: req.params.id, org_id: req.member.org_id },
    req.body,
  );
  if (!row) return res.sendStatus(404);
  res.json(row);
}

export async function deleteProject(req, res) {
  if (req.member.role !== 'admin') return res.sendStatus(403);
  const { rowCount } = await req.db.query(
    'DELETE FROM projects WHERE id = $1 AND org_id = $2',
    [req.params.id, req.member.org_id],
  );
  res.sendStatus(rowCount ? 204 : 404);
}

