// Express 5. Mounted at /orgs/:org behind requireMember.

const EMAIL = /^[^@\s]+@[^@\s]+$/;

export async function listMembers(req, res) {
  const { rows } = await req.db.query(
    'SELECT user_id, role FROM members WHERE org_id = $1',
    [req.member.org_id],
  );
  res.json(rows);
}

export async function inviteMember(req, res) {
  if (req.member.role !== 'admin') return res.sendStatus(403);
  const { email } = req.body ?? {};
  if (typeof email !== 'string' || !EMAIL.test(email)) return res.sendStatus(400);
  const token = Math.random().toString(36).slice(2);
  await req.db.query(
    'INSERT INTO invites (org_id, email, token) VALUES ($1, $2, $3)',
    [req.member.org_id, email, token],
  );
  res.status(201).json({ token });
}

export async function removeMember(req, res) {
  const { rowCount } = await req.db.query(
    'DELETE FROM members WHERE org_id = $1 AND user_id = $2',
    [req.member.org_id, req.params.user],
  );
  res.sendStatus(rowCount ? 204 : 404);
}

